/**
 * Database types for public.apps (stack 08).
 *
 * Hand-written to mirror supabase/migrations/20260101000000_create_apps.sql.
 * In a live project this file would be generated by `supabase gen types`;
 * the migration verifier (scripts/verify-migrations.mjs) plus the data-layer
 * tests keep the two in sync for this reference implementation.
 */

// NOTE: these are *type aliases*, not interfaces. supabase-js 2.x constrains
// schema types with `Row: Record<string, unknown>`, and TypeScript only gives
// implicit index signatures to type aliases — an interface here makes the
// whole `Database` fail the `GenericSchema` constraint, collapsing every
// query result type to `never`.
export type AppStatus = 'draft' | 'active' | 'archived'

export type AppRow = {
  id: string
  user_id: string
  name: string
  description: string
  status: AppStatus
  created_at: string
  updated_at: string
}

export interface Database {
  public: {
    Tables: {
      apps: {
        Row: AppRow
        Insert: Partial<AppRow>
        Update: Partial<AppRow>
        Relationships: [
          {
            foreignKeyName: 'apps_user_id_fkey'
            columns: ['user_id']
            isOneToOne: false
            referencedRelation: 'users'
            referencedColumns: ['id']
          },
        ]
      }
    }
    Views: Record<string, never>
    Functions: Record<string, never>
    Enums: Record<string, never>
    CompositeTypes: Record<string, never>
  }
}
